type SeedFarmer = {
  slug: string;
  contactName: string;
  farmName: string;
  phone: string;
  email: string;
  region: string;
  about: string;
  aboutTa: string;
  status: "PENDING" | "VERIFIED" | "REJECTED" | "SUSPENDED";
  govtIdLast4?: string;
  // "Certified organic" is regulated in India. A verified farm has to carry the
  // scheme it is certified under, the certificate number and its expiry.
  certifier?: string;
  certificateNo?: string;
  certifiedUntil?: string;
  // Days before today that this farm was last checked, so the site does not show
  // the same check date on every listing.
  checkedDaysAgo?: number;
};

