async function main() {
  const farmerIdBySlug = new Map<string, string>();

  // Districts are their own table, so the Tamil spelling lives with the data
  // rather than in a hard-coded map in the UI layer.
  const regionIdByName = new Map<string, string>();
  for (const region of regions) {
    const saved = await prisma.region.upsert({
      where: { slug: region.slug },
      update: { name: region.name, nameTa: region.nameTa },
      create: region,
      select: { id: true, name: true },
    });
    regionIdByName.set(saved.name, saved.id);
  }

  for (const farmer of farmers) {
    const { status, certifiedUntil, checkedDaysAgo, region, ...rest } = farmer;
    const regionId = regionIdByName.get(region);
    if (!regionId) throw new Error(`Unknown region "${region}" on ${farmer.slug}`);

    const data = {
      ...rest,
      regionId,
      status,
      photoUrl: `/farms/${farmer.slug}.svg`,
      certifiedUntil: certifiedUntil ? new Date(certifiedUntil) : null,
      verifiedAt:
        status === "VERIFIED"
          ? new Date(Date.now() - (checkedDaysAgo ?? 0) * 86_400_000)
          : null,
    };
    const saved = await prisma.farmer.upsert({
      where: { slug: farmer.slug },
      update: data,
      create: data,
    });
    farmerIdBySlug.set(farmer.slug, saved.id);
  }

  for (const category of catalog) {
    const { products, ...categoryData } = category;
    const ta = categoryTa[categoryData.slug];
    const data = {
      ...categoryData,
      nameTa: ta?.name ?? null,
      descriptionTa: ta?.description ?? null,
    };

    const savedCategory = await prisma.category.upsert({
      where: { slug: categoryData.slug },
      update: data,
      create: data,
    });

    for (const product of products) {
      const { farmerSlug, ...productData } = product;
      const farmerId = farmerIdBySlug.get(farmerSlug);
      if (!farmerId) throw new Error(`Unknown farmerSlug "${farmerSlug}" on ${product.slug}`);

      const art = artFor(product.slug);
      const productTamil = productTa[product.slug];
      const { region: productRegion, ...restProduct } = productData;
      const data = {
        ...restProduct,
        // The listing's district is the farm's district; storing a second copy
        // is how they drifted apart before.
        regionId: productRegion ? (regionIdByName.get(productRegion) ?? null) : null,
        nameTa: productTamil?.name ?? null,
        descriptionTa: productTamil?.description ?? null,
        imageUrl: art,
        categoryId: savedCategory.id,
        farmerId,
      };
      const saved = await prisma.product.upsert({
        where: { slug: product.slug },
        update: data,
        create: data,
      });

      // One image per product. The old seed fabricated three "views" out of
      // unrelated clipart, which the gallery then presented as camera angles.
      await prisma.productImage.deleteMany({ where: { productId: saved.id } });
      await prisma.productImage.create({
        data: { productId: saved.id, url: art, position: 0, alt: null },
      });
    }
  }

  const [categories, products, farmerCount, verified, images] = await Promise.all([
    prisma.category.count(),
    prisma.product.count(),
    prisma.farmer.count(),
    prisma.farmer.count({ where: { status: "VERIFIED" } }),
    prisma.productImage.count(),
  ]);

  console.log(
    `Seed complete: ${categories} categories, ${products} products, ${images} images, ` +
      `${farmerCount} farmers (${verified} verified).`,
  );
}

main()
  .catch((error) => {
    console.error("Seed failed:", error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
